def skill():
    t = Symbol('t')
    v1 = 3*t**2 - 21*t + 30
    v2 = 3*t - 6
    D = integrate(v1 - v2, t)
    k = [r for r in solve(D, t) if r > 0][0]
    def dist(v, T):
        F = integrate(v, t)
        pts = [0] + sorted(r for r in solve(v, t) if 0 < r < T) + [T]
        return sum(abs(F.subs(t, b) - F.subs(t, a)) for a, b in zip(pts[:-1], pts[1:]))
    return dist(v1, k) + dist(v2, k)

def standard():
    t = Symbol('t')
    v1 = 3*t**2 - 21*t + 30
    v2 = 3*t - 6
    x1, x2 = integrate(v1, t), integrate(v2, t)
    ks = [r for r in solve(x1 - x2, t) if r.is_real and r > 0]
    k = min(ks)
    return integrate(Abs(v1), (t, 0, k)) + integrate(Abs(v2), (t, 0, k))

def unique():
    return [standard()]
